        lst.sort((p, q) => horiz ? p[1][0] - q[1][0] : p[1][1] - q[1][1]);
        lst.forEach(([me], k) => { const n = lst.length, frac = n > 1 ? (horiz ? 0.12 + 0.76 * (k + 1) / (n + 1) : 0.15 + 0.7 * (k + 1) / (n + 1)) : 0.5; const pt = sidePoint(me.box, me.side, frac); me.x = pt[0]; me.y = pt[1]; });
